CREATE TABLE IF NOT EXISTS tasks (id VARCHAR(36) PRIMARY KEY, goal VARCHAR(500) NOT NULL, scenario VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL);
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS model_mode VARCHAR(20) DEFAULT 'mock' NOT NULL;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS workspace_id VARCHAR(36);
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS file_scope VARCHAR(2000);
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS write_enabled BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS bug_id VARCHAR(80);
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS memory_enabled BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS constraints_json VARCHAR(20000) DEFAULT '[]' NOT NULL;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS acceptance_json VARCHAR(20000) DEFAULT '[]' NOT NULL;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS entry_kind VARCHAR(30) DEFAULT 'GENERAL' NOT NULL;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS file_scopes_json VARCHAR(20000) DEFAULT '[]' NOT NULL;
CREATE TABLE IF NOT EXISTS task_role_budgets (task_id VARCHAR(36) NOT NULL, role_code VARCHAR(30) NOT NULL, policy_version INT NOT NULL, max_model_calls INT, max_tool_calls INT, PRIMARY KEY(task_id, role_code), CHECK(policy_version=1), CHECK(role_code IN ('ANALYST','CODER','REVIEWER')), CHECK(max_model_calls IS NULL OR max_model_calls BETWEEN 1 AND 20), CHECK(max_tool_calls IS NULL OR max_tool_calls BETWEEN 0 AND 20), CHECK(max_model_calls IS NOT NULL OR max_tool_calls IS NOT NULL));
CREATE TABLE IF NOT EXISTS task_tool_budgets (task_id VARCHAR(36) NOT NULL, tool_kind VARCHAR(40) NOT NULL, policy_version INT NOT NULL, max_calls INT NOT NULL, PRIMARY KEY(task_id, tool_kind), CHECK(policy_version=1), CHECK(tool_kind IN ('SIMULATED_INSPECTION','WORKSPACE_READ','WORKSPACE_WRITE')), CHECK(max_calls BETWEEN 0 AND 20));
CREATE TABLE IF NOT EXISTS runs (id VARCHAR(36) PRIMARY KEY, task_id VARCHAR(36) NOT NULL, parent_id VARCHAR(36), status VARCHAR(30) NOT NULL, reason VARCHAR(1000), result VARCHAR(2000), rounds INT NOT NULL, tools INT NOT NULL, max_rounds INT NOT NULL, max_tools INT NOT NULL, max_seconds INT NOT NULL, elapsed_ms BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
ALTER TABLE runs ADD COLUMN IF NOT EXISTS max_per_tool INT DEFAULT 20 NOT NULL;
ALTER TABLE runs ADD COLUMN IF NOT EXISTS max_reported_tokens BIGINT;
ALTER TABLE runs ADD COLUMN IF NOT EXISTS max_identical_tools INT;
ALTER TABLE runs ADD COLUMN IF NOT EXISTS max_agent_rounds INT;
ALTER TABLE runs ADD COLUMN IF NOT EXISTS max_agent_tools INT;
ALTER TABLE runs ADD COLUMN IF NOT EXISTS recovery_dispatch VARCHAR(30) DEFAULT 'UNKNOWN' NOT NULL;
ALTER TABLE runs ADD COLUMN IF NOT EXISTS stop_cause VARCHAR(40);
CREATE TABLE IF NOT EXISTS events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id VARCHAR(36) NOT NULL, event_type VARCHAR(50) NOT NULL, message VARCHAR(2000) NOT NULL, created_at VARCHAR(40) NOT NULL);
ALTER TABLE events ADD COLUMN IF NOT EXISTS reason_code VARCHAR(50);
CREATE TABLE IF NOT EXISTS checkpoints (id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, version INT NOT NULL, stage VARCHAR(30) NOT NULL, rounds INT NOT NULL, tools INT NOT NULL, elapsed_ms BIGINT NOT NULL, tool_result VARCHAR(2000), event_id BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL);
ALTER TABLE checkpoints ADD COLUMN IF NOT EXISTS checksum VARCHAR(64);
ALTER TABLE checkpoints ADD COLUMN IF NOT EXISTS engine VARCHAR(30) DEFAULT 'LEGACY' NOT NULL;
CREATE TABLE IF NOT EXISTS agent_invocations (id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, role_name VARCHAR(80) NOT NULL, task_goal VARCHAR(500) NOT NULL, status VARCHAR(30) NOT NULL, result VARCHAR(2000), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
ALTER TABLE agent_invocations ADD COLUMN IF NOT EXISTS role_code VARCHAR(30);
ALTER TABLE agent_invocations ADD COLUMN IF NOT EXISTS role_version INT;
CREATE TABLE IF NOT EXISTS agent_skills (agent_id VARCHAR(36) NOT NULL, skill_id VARCHAR(40) NOT NULL, skill_version INT NOT NULL, content_sha256 VARCHAR(64) NOT NULL, created_at VARCHAR(40) NOT NULL, PRIMARY KEY(agent_id, skill_id));
CREATE TABLE IF NOT EXISTS agent_tool_loads (agent_id VARCHAR(36) PRIMARY KEY, loaded_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS agent_tool_grants (agent_id VARCHAR(36) NOT NULL, tool_kind VARCHAR(40) NOT NULL, PRIMARY KEY(agent_id, tool_kind));
ALTER TABLE agent_tool_grants ADD COLUMN IF NOT EXISTS tool_version INT;
CREATE TABLE IF NOT EXISTS plan_nodes (id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, sequence_no INT NOT NULL, role_code VARCHAR(30) NOT NULL, prerequisite_role VARCHAR(30), status VARCHAR(30) NOT NULL, agent_id VARCHAR(36), started_at VARCHAR(40), finished_at VARCHAR(40), UNIQUE(run_id, role_code), UNIQUE(run_id, sequence_no), UNIQUE(agent_id));
ALTER TABLE plan_nodes ADD COLUMN IF NOT EXISTS source_agent_id VARCHAR(36);
CREATE TABLE IF NOT EXISTS handoffs (id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, agent_id VARCHAR(36) NOT NULL, direction VARCHAR(30) NOT NULL, payload CLOB NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS handoff_receipts (handoff_id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, receiver_agent_id VARCHAR(36) NOT NULL UNIQUE, received_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS tool_invocations (id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, agent_id VARCHAR(36) NOT NULL, tool_name VARCHAR(80) NOT NULL, status VARCHAR(30) NOT NULL, result VARCHAR(2000), error_message VARCHAR(1000), duration_ms BIGINT, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
ALTER TABLE tool_invocations ADD COLUMN IF NOT EXISTS tool_version INT;
CREATE TABLE IF NOT EXISTS tool_attempt_fingerprints (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id VARCHAR(36) NOT NULL, tool_id VARCHAR(36) NOT NULL UNIQUE, kind VARCHAR(40) NOT NULL, fingerprint VARCHAR(64) NOT NULL);
CREATE TABLE IF NOT EXISTS model_invocations (id VARCHAR(36) PRIMARY KEY, run_id VARCHAR(36) NOT NULL, agent_id VARCHAR(36) NOT NULL, model_name VARCHAR(80) NOT NULL, status VARCHAR(30) NOT NULL, input_tokens INT, output_tokens INT, duration_ms BIGINT, error_message VARCHAR(1000), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id VARCHAR(36) PRIMARY KEY, repository_path VARCHAR(2000) NOT NULL, workspace_path VARCHAR(2000) NOT NULL, base_branch VARCHAR(500) NOT NULL, base_commit VARCHAR(64) NOT NULL, branch_name VARCHAR(500) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS bug_checks (id VARCHAR(36) PRIMARY KEY, bug_id VARCHAR(80) NOT NULL, workspace_id VARCHAR(36) NOT NULL, kind VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, output CLOB, duration_ms BIGINT NOT NULL, created_at VARCHAR(40) NOT NULL);
ALTER TABLE bug_checks ADD COLUMN IF NOT EXISTS workspace_fingerprint VARCHAR(64);
ALTER TABLE bug_checks ADD COLUMN IF NOT EXISTS run_id VARCHAR(36);
CREATE TABLE IF NOT EXISTS approvals (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, fingerprint VARCHAR(64) NOT NULL, status VARCHAR(30) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS bug_feedback (id VARCHAR(36) PRIMARY KEY, bug_id VARCHAR(80) NOT NULL, workspace_id VARCHAR(36) NOT NULL, status VARCHAR(40) NOT NULL, note VARCHAR(1000), created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS evaluation_batches (id VARCHAR(36) PRIMARY KEY, suite VARCHAR(40) NOT NULL, status VARCHAR(30) NOT NULL, created_at VARCHAR(40) NOT NULL, finished_at VARCHAR(40));
ALTER TABLE evaluation_batches ADD COLUMN IF NOT EXISTS definition_json CLOB;
ALTER TABLE evaluation_batches ADD COLUMN IF NOT EXISTS definition_sha256 VARCHAR(64);
CREATE TABLE IF NOT EXISTS evaluation_cases (id VARCHAR(36) PRIMARY KEY, batch_id VARCHAR(36) NOT NULL, case_code VARCHAR(40) NOT NULL, sequence_no INT NOT NULL, status VARCHAR(30) NOT NULL, run_id VARCHAR(36), explanation VARCHAR(1000), updated_at VARCHAR(40) NOT NULL, UNIQUE(batch_id, case_code));
CREATE TABLE IF NOT EXISTS evaluation_checks (case_id VARCHAR(36) NOT NULL, sequence_no INT NOT NULL, check_code VARCHAR(50) NOT NULL, passed BOOLEAN NOT NULL, detail VARCHAR(1000) NOT NULL, PRIMARY KEY(case_id, check_code), UNIQUE(case_id, sequence_no));
CREATE TABLE IF NOT EXISTS memory_records (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, category VARCHAR(30) NOT NULL, content VARCHAR(300) NOT NULL, source VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, version INT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS memory_history (memory_id VARCHAR(36) NOT NULL, version INT NOT NULL, category VARCHAR(30) NOT NULL, content VARCHAR(300) NOT NULL, status VARCHAR(20) NOT NULL, changed_at VARCHAR(40) NOT NULL, PRIMARY KEY(memory_id, version));
CREATE TABLE IF NOT EXISTS run_memory_loads (run_id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, item_count INT NOT NULL, loaded_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS run_memory_references (run_id VARCHAR(36) NOT NULL, sequence_no INT NOT NULL, memory_id VARCHAR(36) NOT NULL, memory_version INT NOT NULL, category VARCHAR(30) NOT NULL, PRIMARY KEY(run_id, sequence_no), UNIQUE(run_id, memory_id));
CREATE TABLE IF NOT EXISTS git_actions (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, kind VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, approval_id VARCHAR(36) NOT NULL, commit_id VARCHAR(64), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
